package org.sleepwell.app;
import android.content.Context;import android.os.SystemClock;import java.util.concurrent.*;import java.util.function.*;
/** Optional direct-Hue owner. Root alarm hooks only start/close this bounded off-main work. */
final class HueBridgeAlarm implements AutoCloseable {
 private static final ScheduledExecutorService WORKER=Executors.newSingleThreadScheduledExecutor(r->new Thread(r,"SleepWell Hue bridge"));private static HueBridgeAlarm current,test;
 private final Context app;private final long started;private final BooleanSupplier alarmOwner;private final boolean testing;private final HueBridgeConfig explicit;private volatile boolean closed;private HueBridgeConfig config;private HueBridgeRun run;private ScheduledFuture<?> periodic;private long queuedAt=Long.MIN_VALUE;private final java.util.concurrent.atomic.AtomicBoolean pending=new java.util.concurrent.atomic.AtomicBoolean();
 private HueBridgeAlarm(Context context,long started,BooleanSupplier owner,boolean testing,HueBridgeConfig explicit){app=context.getApplicationContext();this.started=started;alarmOwner=owner;this.testing=testing;this.explicit=explicit;}
 static synchronized HueBridgeAlarm start(Context context,Alarm alarm,String occurrence,long started,BooleanSupplier alive){if(alarm.id<=0||new AlarmWakePolicy(alarm).quiet||!BackupRuntime.nonce(occurrence)||!HueBridgeSettings.enabled(context))return null;stopTest();if(HueBridgeSettings.homeAssistant(context)){HueBridgeSettings.status(context,HueBridgeSettings.prefs(context).getLong("revision",0),"Both lamp paths are enabled. Disable Home Assistant before using direct Hue; no direct Hue control started.");return null;}if(current!=null)current.close();HueBridgeAlarm owner=new HueBridgeAlarm(context,started,alive,false,null);current=owner;owner.periodic=WORKER.scheduleWithFixedDelay(owner::tick,0,5,TimeUnit.SECONDS);return owner;}
 private boolean owns(){synchronized(HueBridgeAlarm.class){return !closed&&(testing?test==this:current==this)&&alarmOwner.getAsBoolean();}}
 private boolean configured(){return config!=null&&HueBridgeSettings.current(app,config.revision,!testing);}
 static boolean enabled(Context context){return HueBridgeSettings.enabled(context);}
 synchronized void tick(){long now=SystemClock.elapsedRealtime();if(closed||queuedAt!=Long.MIN_VALUE&&now-queuedAt<5000||!pending.compareAndSet(false,true))return;queuedAt=now;WORKER.execute(()->{try{pump();}finally{pending.set(false);}});}
 private void pump(){if(!owns()){close();return;}try{if(config==null){config=explicit==null?HueBridgeSettings.load(app):explicit;config.validate();if(!HueBridgeSettings.current(app,config.revision,!testing)){close();return;}run=new HueBridgeRun(config,()->owns()&&configured(),()->configured(),message->HueBridgeSettings.status(app,config.revision,message));}if(!configured()){close();return;}run.tick(testing?60000:Math.max(0,SystemClock.elapsedRealtime()-started));}catch(Exception unavailable){long revision=HueBridgeSettings.prefs(app).getLong("revision",0);HueBridgeSettings.status(app,revision,"Hue bridge is unavailable. The phone alarm is independent; review the saved connection.");close();}}
 @Override public void close(){synchronized(HueBridgeAlarm.class){if(closed)return;closed=true;if(current==this)current=null;if(test==this)test=null;}if(periodic!=null)periodic.cancel(false);WORKER.execute(()->{if(run!=null)run.close();});}
 static synchronized boolean test(Context context,HueBridgeConfig saved){if(current!=null||AlarmService.active||Prefs.flag(context,"ringing")||TrackingService.running||!HueBridgeSettings.current(context,saved.revision,false))return false;stopTest();HueBridgeConfig low=new HueBridgeConfig(saved.address,saved.identity,saved.pin,saved.key,saved.light,saved.name,true,1,Math.min(5,saved.maximum),true,saved.revision);HueBridgeAlarm owner=new HueBridgeAlarm(context,SystemClock.elapsedRealtime(),()->!AlarmService.active&&!Prefs.flag(context,"ringing")&&!TrackingService.running,true,low);test=owner;WORKER.execute(owner::tick);WORKER.schedule(owner::close,3,TimeUnit.SECONDS);return true;}
 static synchronized void stopTest(){if(test!=null)test.close();}
 static synchronized boolean active(){return current!=null&&!current.closed;}
 static synchronized void stop(){if(current!=null)current.close();stopTest();}
}
